def transform(grid):
    # Split the disconnected 3-colored patches; their 9 marks encode compact patterns.
    seen=set(); comps=[]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v != 3 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<len(grid) and 0<=p[1]<len(row) and grid[p[0]][p[1]]==3 and p not in seen:
                        seen.add(p); stack.append(p)
            comps.append(cells)
    return grid
